from pathlib import Path
import json,sys,contextlib,io
sys.argv=['analyze_scaled_pool_legs.py','/home/ubuntu/spacepdhcg-scaled-followup-v549']
with contextlib.redirect_stdout(io.StringIO()):exec(compile("from pathlib import Path\nimport collections\nimport json\nimport sys\n\nroot = Path(sys.argv[1])\nreport = json.loads((root / 'report.json').read_text())\nassert report['complete'] and not report.get('error')\ngroups = {name: json.loads((root / name / 'results.json').read_text())\n          for name in ['baseline', 'candidate']}\nresult = {}\nfor name, rows in groups.items():\n    assert [row['index'] for row in rows] == list(range(225))\n    assert all(row.get('certified', False) for row in rows if row['status'] == 'converged')\n    result[name] = dict(\n        seconds=sum(row['seconds'] for row in rows),\n        converged=sum(row['status'] == 'converged' for row in rows),\n        priming=sum(row['priming'] for row in rows),\n        workspaces=sum(row['workspace_creations'] for row in rows),\n        statuses=dict(collections.Counter(row['status'] for row in rows)),\n    )\nlost = []\ndifferences = []\nfor old, new in zip(groups['baseline'], groups['candidate'], strict=True):\n    if old['status'] == 'converged':\n        if new['status'] != 'converged':\n            lost.append(old['index'])\n        else:\n            differences.append(dict(index=old['index'], delta_kg=abs(\n                old['certificate']['final_mass_kg'] - new['certificate']['final_mass_kg'])))\nresult.update(\n    scope='One full pass per mode with identical core and QOCO binaries, two objective-preserving Ruiz passes in both modes. Baseline rebuilds scaled workspaces; candidate reuses compatible ones. Original budgets and accuracy tolerances unchanged. Solver time excludes certification.',\n    lost_baseline=lost,\n    max_certified_mass_delta=max(differences, key=lambda x: x['delta_kg']),\n    less_time_percent=100 * (1 - result['candidate']['seconds'] / result['baseline']['seconds']),\n    largest_timing_changes=sorted([\n        dict(index=a['index'], baseline_seconds=a['seconds'], candidate_seconds=b['seconds'],\n             difference=b['seconds'] - a['seconds'], baseline_iterations=a['iterations'],\n             candidate_iterations=b['iterations'])\n        for a, b in zip(groups['baseline'], groups['candidate'], strict=True)\n    ], key=lambda row: -abs(row['difference']))[:10],\n)\n(root / 'analysis.json').write_text(json.dumps(result, indent=2))\nprint(json.dumps(result, indent=2))\n",'analyze_scaled_pool_legs.py',"exec"))
print(Path('/home/ubuntu/spacepdhcg-scaled-followup-v549/analysis.json').read_text())
sys.argv=['analyze_scaled_pool_campaign.py','/home/ubuntu/spacepdhcg-scaled-pool-campaign-v548']
with contextlib.redirect_stdout(io.StringIO()):exec(compile("from pathlib import Path\nimport json\nimport statistics\nimport sys\n\nroot = Path(sys.argv[1])\nreport = json.loads((root / 'report.json').read_text())\nassert report['complete'] and not report.get('error')\nrows, plans, counts = [], None, None\nfor c in report['campaigns']:\n    result = json.loads((root / c['name'] / 'output/run_report.json').read_text())\n    best = result['best']\n    assert best['accepted'] and best['official']['ok'] and best['independent']['ok']\n    calls = json.loads((root / c['name'] / 'calls.json').read_text())\n    assert all(call['settings']['qoco_ruiz_iterations'] == (2 if c['candidate'] else 0) for call in calls)\n    current = result['ships'][0]['search']['top_candidates']\n    actual = {k: v for k, v in result['screening'].items() if k.startswith('completed_')}\n    if plans is None:\n        plans, counts = current, actual\n    elapsed = c.get('process_seconds')\n    if elapsed is None:\n        elapsed = next(s['seconds'] for s in report['stages'] if s['name'] == c['name'])\n    rows.append(dict(name=c['name'], candidate=c['candidate'], process_seconds=elapsed,\n                     cli_seconds=result['wall_seconds_total'],\n                     score=best['independent']['weighted_score_fixed_bonus_kg'],\n                     same_initial_plans=current == plans, same_logical_counts=actual == counts,\n                     calls=len(calls), solver_seconds=sum(x['seconds'] for x in calls),\n                     converged=sum(x['status'] == 'converged' for x in calls),\n                     workspace_creations=sum(x['solver_reports'][-1]['workspace_creations']\n                                             for x in calls if x['solver_reports'])))\nbefore, after = [statistics.median(r['process_seconds'] for r in rows if r['candidate'] == mode)\n                 for mode in (False, True)]\noutput = dict(scope='ABBA two runs per mode, identical binary. Zero Ruiz versus two Ruiz passes with objective magnitude preserved; candidate enables compatible scaled workspace reuse; zero-Ruiz baseline uses existing reuse. All runs pass both mission checkers.',\n              baseline_process_median=before, candidate_process_median=after,\n              less_process_time_percent=100 * (1 - after / before), rows=rows)\n(root / 'analysis.json').write_text(json.dumps(output, indent=2))\nprint(json.dumps(output, indent=2))\n",'analyze_scaled_pool_campaign.py',"exec"))
print(Path('/home/ubuntu/spacepdhcg-scaled-pool-campaign-v548/analysis.json').read_text())
